CONEXAO_PATCH = r'''
_conexao_anchor = "def snapshot_df(snap,key): return pd.DataFrame(snap.get(key) or [])\n"
_conexao_impl = "\n# Lê transientes sem converter indisponibilidade em uma lista vazia.\nimport time as _mrp_time\n_MRP_TRANSIENT_HTTP = {408, 429, 500, 502, 503, 504, 520, 521, 522, 523, 524, 525, 526}\n_mrp_read_cache_this_run = {}\n\ndef _mrp_is_transient(error):\n    if isinstance(error, (requests.exceptions.Timeout, requests.exceptions.ConnectionError)):\n        return True\n    if isinstance(error, requests.exceptions.HTTPError):\n        response = getattr(error, \"response\", None)\n        return response is not None and response.status_code in _MRP_TRANSIENT_HTTP\n    return False\n\ndef _mrp_retry_read(fn, what):\n    last = None\n    for attempt in range(4):\n        try:\n            return fn()\n        except requests.exceptions.RequestException as error:\n            last = error\n            if not _mrp_is_transient(error) or attempt == 3:\n                break\n            _mrp_time.sleep((0.8, 1.8, 3.5)[attempt])\n    raise RuntimeError(f\"{what}: conexão indisponível após quatro tentativas. Nenhuma tratativa será ignorada.\") from last\n\n_mrp_original_sb_get = _sb_get\ndef _sb_get(params=None):\n    def run():\n        response = requests.get(\n            f\"{SUPABASE_URL}/rest/v1/mrp_snapshots\",\n            headers=_sb_headers(), params=params or {}, timeout=(8, 50),\n        )\n        if response.status_code == 401 and _refresh_supabase_session():\n            response = requests.get(\n                f\"{SUPABASE_URL}/rest/v1/mrp_snapshots\",\n                headers=_sb_headers(), params=params or {}, timeout=(8, 50),\n            )\n        response.raise_for_status()\n        return response.json()\n    return _mrp_retry_read(run, \"Consulta do histórico MRP\")\n\n_mrp_original_project_request = _tratativas_request\ndef _tratativas_request(method, params=None, payload=None, prefer=None, timeout=30):\n    if str(method).upper() != \"GET\":\n        return _mrp_original_project_request(method, params=params, payload=payload, prefer=prefer, timeout=timeout)\n    return _mrp_retry_read(\n        lambda: _mrp_original_project_request(method, params=params, payload=payload, prefer=prefer, timeout=timeout),\n        \"Leitura das tratativas por projeto\",\n    )\n\n_mrp_original_product_request = _tratativas_produto_request\ndef _tratativas_produto_request(method, params=None, payload=None, prefer=None, timeout=30):\n    if str(method).upper() != \"GET\":\n        return _mrp_original_product_request(method, params=params, payload=payload, prefer=prefer, timeout=timeout)\n    return _mrp_retry_read(\n        lambda: _mrp_original_product_request(method, params=params, payload=payload, prefer=prefer, timeout=timeout),\n        \"Leitura das tratativas por produto\",\n    )\n\n_mrp_original_load_projects = _carregar_tratativas_salvas\ndef _carregar_tratativas_salvas():\n    if \"projetos\" not in _mrp_read_cache_this_run:\n        _mrp_read_cache_this_run[\"projetos\"] = _mrp_original_load_projects()\n    return _mrp_read_cache_this_run[\"projetos\"].copy()\n\n_mrp_original_load_products = _carregar_tratativas_produto_salvas\ndef _carregar_tratativas_produto_salvas():\n    if \"produtos\" not in _mrp_read_cache_this_run:\n        _mrp_read_cache_this_run[\"produtos\"] = _mrp_original_load_products()\n    return _mrp_read_cache_this_run[\"produtos\"].copy()\n\n# Chave única no banco: uma confirmação perdida não cria dois históricos.\ndef _mrp_lookup_saved_calculation(calculation_key):\n    if not calculation_key:\n        return None\n    rows = _sb_get({\n        \"select\": \"id,created_at,calculation_key\",\n        \"calculation_key\": f\"eq.{calculation_key}\",\n        \"limit\": \"1\",\n    })\n    return rows[0] if rows else None\n\ndef _mrp_clear_history_caches():\n    # A recuperação no menu lateral aparece antes da declaração das funções\n    # de histórico; nesse caso limpar o cache global evita exibir um MRP antigo.\n    missing = False\n    for name in (\"load_latest_snapshot_meta\", \"load_snapshot_history\", \"load_snapshot\"):\n        fn = globals().get(name)\n        if fn is None:\n            missing = True\n            continue\n        try:\n            fn.clear()\n        except (AttributeError, TypeError):\n            missing = True\n    if missing:\n        st.cache_data.clear()\n\ndef _sb_post(payload):\n    key = str(payload.get(\"calculation_key\") or \"\").strip()\n    if not key:\n        raise ValueError(\"Identificador do processamento ausente; histórico não enviado.\")\n    queue = st.session_state.setdefault(\"_mrp_pending_snapshots\", {})\n    queue[key] = payload\n    last_error = None\n    for attempt in range(3):\n        # Sempre consulta antes de reenviar: a tentativa anterior pode ter\n        # sido gravada mesmo quando a resposta sofreu timeout.\n        try:\n            existing = _mrp_lookup_saved_calculation(key)\n        except Exception as error:\n            existing = None\n            last_error = error\n        if existing is not None:\n            queue.pop(key, None)\n            _mrp_clear_history_caches()\n            return [existing]\n        try:\n            response = requests.post(\n                f\"{SUPABASE_URL}/rest/v1/mrp_snapshots\",\n                headers={**_sb_headers(), \"Prefer\": \"return=representation\"},\n                json=payload,\n                timeout=(12, 90),\n            )\n            if response.status_code == 401 and _refresh_supabase_session():\n                response = requests.post(\n                    f\"{SUPABASE_URL}/rest/v1/mrp_snapshots\",\n                    headers={**_sb_headers(), \"Prefer\": \"return=representation\"},\n                    json=payload,\n                    timeout=(12, 90),\n                )\n            if response.status_code == 409:\n                existing = _mrp_lookup_saved_calculation(key)\n                if existing is not None:\n                    queue.pop(key, None)\n                    _mrp_clear_history_caches()\n                    return [existing]\n            response.raise_for_status()\n            data = response.json()\n            if not isinstance(data, list) or not data or not data[0].get(\"id\"):\n                raise RuntimeError(\"Resposta de gravação sem ID confirmado.\")\n            queue.pop(key, None)\n            _mrp_clear_history_caches()\n            return data\n        except requests.exceptions.RequestException as error:\n            last_error = error\n            if not _mrp_is_transient(error) or attempt == 2:\n                break\n        except Exception as error:\n            last_error = error\n            break\n        _mrp_time.sleep((1.5, 3.5)[attempt])\n    # Última verificação: o servidor pode ter salvo, mas perdido a resposta.\n    try:\n        existing = _mrp_lookup_saved_calculation(key)\n        if existing is not None:\n            queue.pop(key, None)\n            _mrp_clear_history_caches()\n            return [existing]\n    except Exception:\n        pass\n    raise RuntimeError(\n        \"Salvamento NÃO CONFIRMADO pelo Supabase. O processamento foi mantido \"\n        \"como pendente nesta sessão; use 'SALVAR PENDENTE' para tentar novamente.\"\n    ) from last_error\n\n# A recuperação fica acessível mesmo se a nova leitura das tratativas falhar.\nif st.session_state.get(\"auth_role\") == \"ADMIN\" and st.session_state.get(\"_mrp_pending_snapshots\"):\n    with st.sidebar.expander(\"HISTÓRICO MRP PENDENTE\", expanded=True):\n        st.warning(\"Há processamento(s) calculado(s) sem confirmação de gravação. Não feche esta sessão antes de salvá-los.\")\n        for _mrp_pending_key, _mrp_pending_payload in list(st.session_state[\"_mrp_pending_snapshots\"].items()):\n            _mrp_label = f\"Semana {_mrp_pending_payload.get('semana_mrp') or '-'} · {_mrp_pending_key[:8]}\"\n            if st.button(\"SALVAR PENDENTE — \" + _mrp_label, key=\"mrp_retry_\" + _mrp_pending_key, use_container_width=True):\n                try:\n                    _sb_post(_mrp_pending_payload)\n                    st.session_state[\"_mrp_saved_sig\"] = _mrp_pending_key\n                    st.success(\"Histórico confirmado no banco.\")\n                    st.rerun()\n                except Exception as error:\n                    st.error(str(error))\n"
if _source.count(_conexao_anchor) != 1:
    raise RuntimeError("Ponto de instalação da resiliência Supabase não encontrado.")
_source = _source.replace(_conexao_anchor, _conexao_impl + "\n" + _conexao_anchor, 1)

# Acopla chave idempotente sem alterar cálculo ou regras de negócio.
_sig = 'def save_snapshot(semana,usuario,mrp_geral,projecao_semanal,demanda_projeto,compra_mrp,compras=None,fabricacao=None):'
if _source.count(_sig) != 1:
    raise RuntimeError("Assinatura do snapshot mudou; proteção de histórico não instalada.")
_source = _source.replace(_sig, 'def save_snapshot(semana,usuario,mrp_geral,projecao_semanal,demanda_projeto,compra_mrp,compras=None,fabricacao=None,calculation_key=None):', 1)
_call = '    result=_sb_post(payload)\n'
if _source.count(_call) != 1:
    raise RuntimeError("Chamada de salvamento do snapshot mudou.")
_source = _source.replace(_call, '    payload["calculation_key"]=calculation_key\n' + _call, 1)
_save_call = 'save_snapshot(semana_atual,usuario_mrp,macro,proj,demanda_projeto,compras_mrp,cp,fab_det)'
if _source.count(_save_call) != 1:
    raise RuntimeError("Chamada do processamento MRP mudou.")
_source = _source.replace(_save_call, 'save_snapshot(semana_atual,usuario_mrp,macro,proj,demanda_projeto,compras_mrp,cp,fab_det,calculation_key=_mrp_sig)', 1)

# Uma falha no primeiro salvamento não dispara novos POST a cada filtro/rerun.
_auto_old = '        if st.session_state.get("_mrp_saved_sig")!=_mrp_sig:\n            save_snapshot(semana_atual,usuario_mrp,macro,proj,demanda_projeto,compras_mrp,cp,fab_det,calculation_key=_mrp_sig)\n            st.session_state["_mrp_saved_sig"]=_mrp_sig\n            st.success("MRP salvo no histórico compartilhado.")'
_auto_new = '        if st.session_state.get("_mrp_saved_sig")!=_mrp_sig:\n            if _mrp_sig in st.session_state.get("_mrp_pending_snapshots", {}):\n                st.error("MRP calculado, mas o histórico ainda NÃO está confirmado. Use HISTÓRICO MRP PENDENTE no menu lateral para salvar sem recalcular.")\n            else:\n                save_snapshot(semana_atual,usuario_mrp,macro,proj,demanda_projeto,compras_mrp,cp,fab_det,calculation_key=_mrp_sig)\n                st.session_state["_mrp_saved_sig"]=_mrp_sig\n                st.success("MRP salvo no histórico compartilhado.")'
if _source.count(_auto_old) != 1:
    raise RuntimeError("Fluxo de confirmação automática do MRP mudou.")
_source = _source.replace(_auto_old, _auto_new, 1)

'''
